# =============================================================================
# sleep_step1.R  --  The three monotone-spline calibration methods on the
#                    simulated sleep data set (n = 1000), with standard errors
#                    and 95% intervals
#
#   MS-Joint  concurrent calibration     (items and curve together)
#   MS-EAP    EAP plug-in                (curve regressed on PSQI-only EAPs)
#   MS-Fixed  fixed-item calibration     (PSQI-only items fixed, eta integrated out)
#
# Data: sleep_data() (generated by simulate_sleep_data(), seed 20261003). The
# generating SQI curve is 72 - 8 eta - 1.5 eta^2, sigma = 6; it is used here
# only as the truth to compare against.
#
# Standard errors and 95% intervals (hybrid, decided 2026-10-11):
#   - item parameters, sigma, g1, thresholds b_jk and s_jk, and the probabilistic
#     crosswalk: Monte Carlo draws from the normal approximation of the
#     estimates (ms_vcov(), ms_intervals(); MS_DRAWS draws, default 2000);
#   - the SQI curve mu(eta) (bands and mu(-3..3)): nonparametric bootstrap
#     (persons resampled, every step refitted, including the GRM and the AIC
#     stop), because the normal approximation conditions on the boosting path
#     and gives curve bands about half as wide as the true sampling spread.
# The bootstrap is run for every quantity and written alongside (boot_*
# columns), so the bootstrap-only results of the manuscript (8 October run)
# are the boot_* columns. Neither kind of interval has been validated by
# simulation.
#
# Environment: MS_BOOT (resamples, default 200), MS_DRAWS, MS_CORES,
#   MS_HETERO (1 = log-linear residual SD, default; 0 = constant SD, outputs
#   end in _constsd), CALIBER_OUT (output folder, default "output").
# Run:  Rscript sleep_step1.R   (any folder; outputs go to $CALIBER_OUT)
# Run time: about 1 min for the fits and about 40 min for 200 resamples on 4 cores.
# =============================================================================

suppressPackageStartupMessages({ library(caliber); library(ggplot2) })
items <- paste0("C", 1:7); n_items <- 7; thr_names <- threshold_names(items)
methods <- ms_methods; method_long <- ms_method_labels; method_cols <- ms_method_colours
item_labels <- sleep_item_labels
nodes <- ms_quadrature()$nodes

n_boot  <- as.integer(Sys.getenv("MS_BOOT", "200"))
n_draw  <- as.integer(Sys.getenv("MS_DRAWS", "2000"))
hetero  <- Sys.getenv("MS_HETERO", "1") == "1"   # log-linear residual SD (main) or constant
suffix  <- if (hetero) "" else "_constsd"
n_cores <- as.integer(Sys.getenv("MS_CORES", max(1, parallel::detectCores() - 1)))
seed    <- 20261003
out     <- Sys.getenv("CALIBER_OUT", "output")
dir.create(file.path(out, "data"), recursive = TRUE, showWarnings = FALSE)
dir.create(file.path(out, "figures"), recursive = TRUE, showWarnings = FALSE)
od <- function(f) file.path(out, "data", f); of <- function(f) file.path(out, "figures", f)

dat <- sleep_data()
Y   <- as.matrix(dat[items]); sqi <- dat$SQI; n <- nrow(Y)

# Truth (for comparison only)
truth <- sleep_truth(); truth_act <- truth$act

# ---- Fit ------------------------------------------------------------------------

grm  <- fit_grm(Y)
t0   <- Sys.time()
fits <- fit_three(Y, sqi, grm, hetero = hetero)
cat(sprintf("Three fits in %.1f s\n", as.numeric(difftime(Sys.time(), t0, units = "secs"))))
for (m in methods) {
  f <- fits[[m]]
  cat(sprintf("%-8s AIC stop at iteration %4d (BIC %4d; %s) | df %.2f | sigma(0) %.3f | g1 %.3f | -2logL(C, SQI) %.2f\n",
              m, f$iter, f$iter_bic, f$stop_reason, f$df, f$act$sigma,
              if (hetero) f$act$log_sigma[2] else 0,
              neg2ll_joint(Y, sqi, f$a, f$d, f$act)))
}


# ---- Bootstrap ------------------------------------------------------------------

eta_report <- -3:3
curve_grid <- seq(-3.5, 3, by = 0.05)
summ <- function(f) fit_summary(f, items, eta_report, curve_grid)

cat(sprintf("\nBootstrap: %d resamples x 3 methods on %d cores ...\n", n_boot, n_cores))
t0 <- Sys.time()
# keep_categories = FALSE: no redraw, as in the 8 October run
boot <- ms_bootstrap(Y, sqi, n_boot, seed, summary_fun = summ, keep_categories = FALSE,
                     cores = n_cores, hetero = hetero)
cat(sprintf("Done in %.1f min; %d of %d resamples usable\n",
            as.numeric(difftime(Sys.time(), t0, units = "mins")),
            length(unique(boot$rep)), n_boot))


# ---- Fast intervals --------------------------------------------------------------

sqi_grid <- seq(20, 90, by = 0.5)
fast_target <- function(a, d, act) {
  thr <- threshold_locations(a, d, act)
  c(setNames(a, paste0("a_", items)), setNames(d[, 1], paste0("d1_", items)),
    setNames(d[, 2], paste0("d2_", items)), setNames(d[, 3], paste0("d3_", items)),
    sigma = sigma_sqi(0, act), g1 = if (hetero) act$log_sigma[2] else 0,
    setNames(c(thr$b), paste0("b_", thr_names)), setNames(c(thr$sqi), paste0("s_", thr_names)),
    cw_vec(crosswalk_probabilistic(sqi_grid, a, d, act, items, "PSQI")))
}
cw_vec <- function(cw)                                   # E_<item>_<grid index>
  setNames(unlist(cw), paste0("E_", rep(names(cw), each = nrow(cw)), "_", seq_len(nrow(cw))))
t0 <- Sys.time()
fast <- lapply(methods, function(m)
  ms_intervals(fits[[m]], ms_vcov(fits[[m]], Y, sqi), fast_target, n_draw = n_draw, seed = seed + 2))
names(fast) <- methods
cat(sprintf("Fast intervals (%d draws) for 3 methods in %.1f s\n", n_draw,
            as.numeric(difftime(Sys.time(), t0, units = "secs"))))


# ---- Estimates, thresholds, crosswalk -----------------------------------------------

truth_summary <- c(setNames(truth$a, paste0("a_", items)),
                   setNames(truth$d[, 1], paste0("d1_", items)),
                   setNames(truth$d[, 2], paste0("d2_", items)),
                   setNames(truth$d[, 3], paste0("d3_", items)),
                   sigma = 6, g1 = 0, setNames(mu_sqi(eta_report, truth_act), paste0("mu(", eta_report, ")")),
                   setNames(c(-truth$d / truth$a), paste0("b_", thr_names)),
                   setNames(c(mu_sqi(-truth$d / truth$a, truth_act)), paste0("s_", thr_names)))
report <- names(truth_summary)

estimates <- do.call(rbind, lapply(methods, function(m) {
  pt <- summ(fits[[m]])[report]
  bm <- boot[boot$method == m, report]
  b_lo <- apply(bm, 2, quantile, 0.025); b_hi <- apply(bm, 2, quantile, 0.975)
  b_se <- apply(bm, 2, sd)
  fm <- fast[[m]][match(report, fast[[m]]$param), ]
  use_fast <- !is.na(fm$param)                      # all but mu(eta): bootstrap
  se <- ifelse(use_fast, fm$se, b_se)
  lo <- ifelse(use_fast, fm$lo, b_lo); hi <- ifelse(use_fast, fm$hi, b_hi)
  data.frame(method = m, param = report, true = unname(truth_summary), est = unname(pt),
             interval = ifelse(use_fast, "normal draws", "bootstrap"),
             se = unname(se), lo95 = unname(lo), hi95 = unname(hi),
             cover95 = unname(truth_summary >= lo & truth_summary <= hi),
             boot_se = unname(b_se), boot_lo95 = unname(b_lo), boot_hi95 = unname(b_hi),
             boot_cover95 = unname(truth_summary >= b_lo & truth_summary <= b_hi))
}))
write.csv(estimates, od(paste0("ms_step1_estimates", suffix, ".csv")), row.names = FALSE)

thresholds <- do.call(rbind, lapply(methods, function(m) {
  e <- estimates[estimates$method == m, ]
  g <- function(p, col) e[[col]][match(paste0(p, "_", thr_names), e$param)]
  data.frame(method = m, item = rep(items, 3), k = rep(1:3, each = n_items),
             b_true = g("b", "true"), b_est = g("b", "est"), b_se = g("b", "se"),
             sqi_true = g("s", "true"), sqi_est = g("s", "est"), sqi_se = g("s", "se"),
             sqi_lo95 = g("s", "lo95"), sqi_hi95 = g("s", "hi95"))
}))
write.csv(thresholds, od(paste0("ms_step1_thresholds_sqi", suffix, ".csv")), row.names = FALSE)

central  <- sqi_grid >= quantile(sqi, .01) & sqi_grid <= quantile(sqi, .99)
cw_true  <- crosswalk(sqi_grid, truth$a, truth$d, truth_act, items, "PSQI")
cws <- lapply(methods, function(m) crosswalk(sqi_grid, fits[[m]]$a, fits[[m]]$d, fits[[m]]$act, items, "PSQI"))
names(cws) <- methods
cw_band <- function(m, col, k) {                    # 95% band of E_k from the draws
  f <- fast[[m]]; f[[col]][match(paste0("E_", k, "_", seq_along(sqi_grid)), f$param)]
}
for (m in methods) for (k in c(items, "PSQI")) {
  cws[[m]][[paste0("E_", k, "_lo95")]] <- cw_band(m, "lo", k)
  cws[[m]][[paste0("E_", k, "_hi95")]] <- cw_band(m, "hi", k)
}
cw_truth <- data.frame(method = "truth", cw_true)
cw_truth[setdiff(names(cws[[1]]), names(cw_true))] <- NA
cw_long <- do.call(rbind, c(list(cw_truth),
                            lapply(methods, function(m) data.frame(method = m, cws[[m]]))))
write.csv(cw_long, od(paste0("ms_step1_crosswalk", suffix, ".csv")), row.names = FALSE)

max_dev <- function(cw, prefix)
  max(sapply(items, function(i) max(abs(cw[[paste0(prefix, i)]] -
                                        cw_true[[paste0(prefix, i)]])[central], na.rm = TRUE)))

eta_fine <- seq(-3, 3, by = 0.01)
comparison <- do.call(rbind, lapply(methods, function(m) {
  f <- fits[[m]]; th <- thresholds[thresholds$method == m, ]
  mu_f <- mu_sqi(eta_fine, f$act)
  bm <- boot[boot$method == m, ]
  data.frame(method = m, label = method_long[[m]], iter = f$iter, df = f$df,
             boot_iter_median = median(bm$iter),
             sigma0 = f$act$sigma, g1 = if (hetero) f$act$log_sigma[2] else 0, mu_m3 = mu_sqi(-3, f$act), mu_0 = mu_sqi(0, f$act),
             mu_p3 = mu_sqi(3, f$act),
             flat_to_eta = max(eta_fine[mu_f >= max(mu_f) - 1e-8]),
             neg2ll_C_SQI = neg2ll_joint(Y, sqi, f$a, f$d, f$act),
             thr_sqi_rmse = sqrt(mean((th$sqi_est - th$sqi_true)^2)),
             thr_sqi_maxabs = max(abs(th$sqi_est - th$sqi_true)),
             thr_cover95 = sum(th$sqi_true >= th$sqi_lo95 & th$sqi_true <= th$sqi_hi95),
             thr_cover95_boot = sum(estimates$boot_cover95[estimates$method == m &
                                                           grepl("^s_", estimates$param)]),
             cw_struct_maxabs = max_dev(cws[[m]], "Estar_"),
             cw_prob_maxabs = max_dev(cws[[m]], "E_"))
}))
write.csv(comparison, od(paste0("ms_step1_comparison", suffix, ".csv")), row.names = FALSE)
cat("\nComparison (truth: mu(-3) 82.5, mu(0) 72, mu(3) 34.5, sigma 6, g1 0)\n")
print(cbind(comparison[1], round(comparison[-(1:2)], 3)), row.names = FALSE)

cat("\nThreshold SQI locations (estimates) vs truth\n")
wide <- reshape(thresholds[c("method", "item", "k", "sqi_true", "sqi_est")],
                idvar = c("item", "k", "sqi_true"), timevar = "method", direction = "wide")
print(transform(wide[order(wide$item, wide$k), ], sqi_true = round(sqi_true, 1),
                `sqi_est.MS-Joint` = round(`sqi_est.MS-Joint`, 1),
                `sqi_est.MS-EAP` = round(`sqi_est.MS-EAP`, 1),
                `sqi_est.MS-Fixed` = round(`sqi_est.MS-Fixed`, 1), check.names = FALSE),
      row.names = FALSE)


# ---- Figures --------------------------------------------------------------------------

# 1. SQI curves with bootstrap 95% pointwise bands, one panel per method
curves <- do.call(rbind, lapply(methods, function(m) {
  bm <- boot[boot$method == m, paste0("curve_", seq_along(curve_grid))]
  data.frame(method = m, eta = curve_grid, est = mu_sqi(curve_grid, fits[[m]]$act),
             lo = apply(bm, 2, quantile, 0.025), hi = apply(bm, 2, quantile, 0.975),
             truth = mu_sqi(curve_grid, truth_act))
}))
curves$panel <- factor(paste0(curves$method, ": ", method_long[curves$method]),
                       levels = paste0(methods, ": ", method_long[methods]))
p_curves <- ggplot(curves, aes(eta)) +
  geom_ribbon(aes(ymin = lo, ymax = hi, fill = method), alpha = 0.18) +
  geom_line(aes(y = truth), linetype = "dashed", colour = "grey20") +
  geom_line(aes(y = est, colour = method), linewidth = 0.9) +
  facet_wrap(~ panel) +
  scale_colour_manual(values = method_cols, guide = "none") +
  scale_fill_manual(values = method_cols, guide = "none") +
  coord_cartesian(ylim = c(15, 90)) +
  labs(x = "Latent sleep disturbance (eta; N(0, 1) metric)", y = "mu(eta) = E[SQI | eta]",
       caption = sprintf(paste0("Solid: estimated non-increasing B-spline. Shaded: bootstrap 95%% ",
                                "pointwise interval (%d resamples, every step refitted). ",
                                "Dashed: generating curve. Residual SD: %s."), n_boot,
                                if (hetero) "log-linear in eta" else "constant")) +
  theme_minimal(base_size = 12) +
  theme(panel.border = element_rect(fill = NA, colour = "grey30"),
        plot.caption = element_text(hjust = 0))
ggsave(of(paste0("ms_step1_sqi_curves", suffix, ".png")), p_curves, width = 11, height = 4.6, dpi = 200, bg = "white")

# 2. Wright maps on the SQI scale, one per method
for (m in methods) {
  f <- fits[[m]]
  eta_pv <- plausible_values(f, grm, sqi, seed = seed + 1)
  pv_text <- if (m == "MS-EAP") "one plausible value of eta per person from p(eta | C) (mirt; SQI not used)" else
    "one plausible value of eta per person from p(eta | C, SQI)"
  how <- switch(m,
    "MS-Joint" = "GRM items and the monotone SQI curve estimated together, eta integrated out",
    "MS-EAP"   = "GRM on the PSQI alone; monotone SQI curve regressed on the EAP scores",
    "MS-Fixed" = "GRM on the PSQI alone, items then fixed; monotone SQI curve with eta integrated out")
  wm <- wright_map_sqi(
    person_sqi = mu_sqi(eta_pv, f$act), thr = thresholds[thresholds$method == m, ],
    item_labels = item_labels,
    note = paste0("Note. ", m, " (", tolower(method_long[[m]]), "): ", how, " (n = ", n, "). ",
                  "mu(eta) is a non-increasing cubic B-spline (monotonic likelihood boosting, AIC stop), ",
                  if (hetero) "residual SD log-linear in eta. " else "constant residual SD. ",
                  "Persons: ", pv_text, ", mapped to SQI through mu(eta).\n",
                  "Thresholds: GRM thresholds b_jk placed at mu(b_jk). Each band spans the SQI values at ",
                  "which that category is the median response. Outer bands fade because they are open-ended."))
  ggsave(of(sprintf("ms_step1_wright_map_%s%s.png", sub("MS-", "", m), suffix)), wm,
         width = 10, height = 7.5, dpi = 200, bg = "white")
}

# 3. Probabilistic crosswalk E[C_j | SQI], estimated vs true, one panel per method
cw_plot <- do.call(rbind, lapply(methods, function(m) do.call(rbind, lapply(items, function(i)
  rbind(data.frame(method = m, SQI = sqi_grid, score = cws[[m]][[paste0("E_", i)]], item = i, source = "estimated",
                   lo = cws[[m]][[paste0("E_", i, "_lo95")]], hi = cws[[m]][[paste0("E_", i, "_hi95")]]),
        data.frame(method = m, SQI = sqi_grid, score = cw_true[[paste0("E_", i)]], item = i, source = "true",
                   lo = NA, hi = NA))))))
cw_plot$panel <- factor(paste0(cw_plot$method, ": ", method_long[cw_plot$method]),
                        levels = paste0(methods, ": ", method_long[methods]))
p_cw <- ggplot(cw_plot, aes(SQI, score, colour = item, linetype = source, linewidth = source)) +
  geom_ribbon(data = cw_plot[cw_plot$source == "estimated", ], aes(ymin = lo, ymax = hi, fill = item),
              colour = NA, alpha = 0.12, inherit.aes = TRUE, show.legend = FALSE) +
  geom_line() +
  geom_rug(data = data.frame(SQI = sqi), aes(x = SQI), inherit.aes = FALSE, sides = "b", alpha = 0.15) +
  facet_wrap(~ panel) +
  scale_linetype_manual(values = c(estimated = "solid", true = "dashed"), name = NULL) +
  scale_linewidth_manual(values = c(estimated = 0.9, true = 0.5), name = NULL) +
  scale_colour_manual(values = setNames(hcl.colors(n_items, "Dark 3"), items), name = "Component") +
  scale_fill_manual(values = setNames(hcl.colors(n_items, "Dark 3"), items), guide = "none") +
  coord_cartesian(ylim = c(0, 3)) +
  labs(x = "Actigraphy SQI (digital measure)", y = "E[C | SQI] (0-3)",
       caption = sprintf(paste0("Shaded: pointwise 95%% interval from %d draws of the normal approximation ",
                                "(items, curve, residual SD)."), n_draw)) +
  theme_minimal(base_size = 12) +
  theme(panel.border = element_rect(fill = NA, colour = "grey30"), legend.position = "bottom")
ggsave(of(paste0("ms_step1_expected_scores", suffix, ".png")), p_cw, width = 12, height = 5, dpi = 200, bg = "white")

write.csv(boot[, !grepl("^curve_", names(boot))], od(paste0("ms_step1_bootstrap", suffix, ".csv")), row.names = FALSE)
cat(sprintf("\nWrote %s/data/ms_step1_*.csv and %s/figures/ms_step1_*.png\n", out, out))
